```java
// ─── File: ThreadFactoryDemo.java ───
// Runnable demo. In a real project each class lives in its own file.
package com.bank.settlement;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;

public class ThreadFactoryDemo {
    private static final Logger LOG = Logger.getLogger("Settlement");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        ThreadFactory factory = new BankThreadFactory("settlement-pool", false);
        ExecutorService pool = Executors.newFixedThreadPool(2, factory);

        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        SettlementService service = new SettlementService(pool, LOG);

        service.settle(rajesh, new BigDecimal("50000"));
        service.settle(rajesh, new BigDecimal("30000"));
        service.settleFaulty();   // throws to prove UncaughtExceptionHandler fires

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
        LOG.info(() -> "Final balance for SAV2001 = Rs." + rajesh.getBalance());
    }
}

// ─── Would be in concurrent/BankThreadFactory.java ───
class BankThreadFactory implements ThreadFactory {
    private static final Logger LOG = Logger.getLogger("Settlement");
    private final String prefix;
    private final boolean daemon;
    private final AtomicInteger counter = new AtomicInteger(0);

    BankThreadFactory(String prefix, boolean daemon) {
        this.prefix = prefix;
        this.daemon = daemon;
    }

    @Override
    public Thread newThread(Runnable r) {
        Thread t = new Thread(r, prefix + "-thread-" + counter.incrementAndGet());
        t.setDaemon(daemon);                        // daemon so JVM shutdown is not blocked
        t.setPriority(Thread.NORM_PRIORITY);        // priority is only a hint to the OS
        t.setUncaughtExceptionHandler((th, ex) ->   // catch escapes from execute()
            LOG.log(Level.SEVERE, "Uncaught exception in " + th.getName(), ex));
        return t;
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String id;
    private final String holder;
    private volatile BigDecimal balance;
    Account(String id, String holder, BigDecimal balance) {
            this.id = id;
            this.holder = holder
            this.balance = balance;
    }
    synchronized void debit(BigDecimal amt) { balance = balance.subtract(amt); }
    BigDecimal getBalance() { return balance; }
    String getId() { return id; }
}

// ─── Would be in service/SettlementService.java ───
class SettlementService {
    private final ExecutorService pool;
    private final Logger log;
        SettlementService(ExecutorService pool, Logger log) { this.pool = pool;
        this.log = log; }

    void settle(Account acct, BigDecimal amount) {
        pool.submit(() -> {
            acct.debit(amount);
            log.info(() -> Thread.currentThread().getName()
                + " settled Rs." + amount + " on " + acct.getId());
        });
    }

    // Uses execute(), not submit(), so the exception escapes to the handler.
    void settleFaulty() {
        pool.execute(() -> { throw new IllegalStateException("corrupt trade record"); });
    }
}
```

