// ─── File: src/test/java/com/bank/settlement/concurrent/BankThreadFactoryTest.java ───
package com.bank.settlement.concurrent;

import org.junit.jupiter.api.Test;
import java.util.concurrent.ThreadFactory;
import static org.junit.jupiter.api.Assertions.*;

class BankThreadFactoryTest {
    @Test
    void namesAreSequentialAndPrefixed() {
        ThreadFactory f = new BankThreadFactory("settlement-pool", true);
        Thread a = f.newThread(() -> {});
        Thread b = f.newThread(() -> {});
        assertEquals("settlement-pool-thread-1", a.getName());
        assertEquals("settlement-pool-thread-2", b.getName());
        assertTrue(a.isDaemon());
        assertNotNull(a.getUncaughtExceptionHandler());
    }
}
